// Created: 2026-04-03

/**
 * Shared cryptographic and sanitization utilities for webhook payloads.
 *
 * signPayload(): HMAC-SHA256 signature for webhook authentication.
 * sanitizePayload(): Strips sensitive keys and truncates long values
 *   before payloads leave the machine. Prevents secret leakage via
 *   tool_input (Bash commands, env vars) and tool_output.
 *
 * Extracted from usage-summary-reporter.ts (#1257) to share across
 * webhookForwarder and usageSummaryReporter.
 */

import { createHmac } from 'node:crypto';

// Keys whose values should be redacted (case-insensitive substring match)
const SENSITIVE_KEYS = ['password', 'secret', 'token', 'key', 'credential', 'auth'];

// Patterns in string VALUES that indicate embedded secrets
// #4218: every pattern carries the `g` flag so multiple secrets in one string
// are all redacted (without it, String.replace stops after the first match).
const SECRET_VALUE_PATTERNS = [
  /sk-ant-[a-zA-Z0-9-]{20,}/g,                  // Anthropic API keys (sk-ant-api03-...)
  /sk-[a-zA-Z0-9]{20,}/g,                       // OpenAI API keys (sk-...)
  /ghp_[a-zA-Z0-9]{36,}/g,                      // GitHub PATs
  /gl(?:pat|ptt|dt|rt|oas|agent|imt|soat|cbt|ft|ffct)-[a-zA-Z0-9_-]{20,}/g, // GitLab tokens (#3589)
  /gho_[a-zA-Z0-9]{36,}/g,                      // GitHub OAuth tokens
  /github_pat_[a-zA-Z0-9_]{60,}/g,              // GitHub fine-grained PATs
  /xoxb-[a-zA-Z0-9-]{20,}/g,                    // Slack bot tokens
  /xoxp-[a-zA-Z0-9-]{20,}/g,                    // Slack user tokens
  /AKIA[A-Z0-9]{16}/g,                          // AWS Access Key IDs
  /AIza[a-zA-Z0-9_-]{35}/g,                    // Google/Firebase API keys
  /Bearer\s+[a-zA-Z0-9._-]{20,}/g,             // Bearer tokens in headers
  /(?:export\s+\w*(?:KEY|TOKEN|SECRET|PASSWORD|CREDENTIAL)\w*\s*=\s*)([^\s;]+)/gi, // env var assignments
  /(?:mongodb(?:\+srv)?:\/\/)[^\s]+/g,           // MongoDB connection strings
  /(?:postgres(?:ql)?:\/\/)[^\s]+/g,             // PostgreSQL connection strings
  /(?:mysql:\/\/)[^\s]+/g,                       // MySQL connection strings
];

const MAX_STRING_LENGTH = 500;

/**
 * HMAC-SHA256 signature for webhook payload verification.
 * Format: sha256=<hex-digest>
 */
export function signPayload(body: string, secret: string): string {
  return `sha256=${createHmac('sha256', secret).update(body).digest('hex')}`;
}

/**
 * Redact a string value that contains embedded secrets.
 * Returns the original string if no secrets detected.
 */
export function redactSecretValues(value: string): string {
  let result = value;
  for (const pattern of SECRET_VALUE_PATTERNS) {
    result = result.replace(pattern, (match) => {
      // Connection URLs: redact the whole match. The prefix heuristic below
      // keeps match.slice(0, prefixEnd) where prefixEnd is the last 20+
      // [A-Za-z0-9._-] run; on Atlas/RDS hosts that run is the hostname, so
      // scheme://user:password@ would survive (#4217 estate-3 HOLD).
      if (/^[a-z][a-z0-9+.-]*:\/\//i.test(match)) {
        return '[REDACTED]';
      }
      // Keep the prefix (export, Bearer, etc.) but redact the secret part
      const prefixEnd = match.search(/[a-zA-Z0-9._-]{20,}$/);
      if (prefixEnd > 0) {
        return `${match.slice(0, prefixEnd)}[REDACTED]`;
      }
      return '[REDACTED]';
    });
  }
  return result;
}

/**
 * Recursively sanitize a single value for egress (HttpSink / JsonlSink).
 * Strings: redact known token shapes then truncate to MAX_STRING_LENGTH.
 * Arrays: map each element (including string argv / MultiEdit / MCP args).
 * Plain objects: sanitizePayload (sensitive keys + recursive values).
 */
function sanitizeValue(value: unknown): unknown {
  if (typeof value === 'string') {
    let processed = redactSecretValues(value);
    if (processed.length > MAX_STRING_LENGTH) {
      processed = `${processed.slice(0, MAX_STRING_LENGTH - 3)}...`;
    }
    return processed;
  }
  if (Array.isArray(value)) {
    return value.map((item) => sanitizeValue(item));
  }
  if (typeof value === 'object' && value !== null) {
    return sanitizePayload(value as Record<string, unknown>);
  }
  return value;
}

/**
 * Sanitize an object for safe transmission over the network.
 * - Redacts values of sensitive keys (password, secret, token, etc.)
 * - Detects and redacts embedded secrets in string values (API keys, Bearer tokens)
 * - Truncates long strings to MAX_STRING_LENGTH
 * - Recursively processes nested objects and array elements (including strings)
 * - Returns undefined for undefined input (pass-through)
 */
export function sanitizePayload(
  obj: Record<string, unknown> | undefined
): Record<string, unknown> | undefined {
  if (!obj) return undefined;

  const sanitized: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(obj)) {
    // Redact sensitive keys entirely
    if (SENSITIVE_KEYS.some(s => key.toLowerCase().includes(s))) {
      sanitized[key] = '[REDACTED]';
      continue;
    }

    sanitized[key] = sanitizeValue(value);
  }

  return sanitized;
}
